CREATE INDEX IF NOT EXISTS idx_land_covers_staging_geom_hash_full
  ON land_covers_staging (parcel_id, sheet_id, land_cover_class_code, geom_hash);
CREATE INDEX IF NOT EXISTS idx_land_covers_staging_parcel_sheet_class
  ON land_covers_staging (parcel_id, sheet_id, land_cover_class_code);

CREATE OR REPLACE FUNCTION public.swap_staging_with_live(p_table_name text)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_table_name NOT IN ('land_covers', 'land_parcels') THEN
    RAISE EXCEPTION 'cannot swap staging with live for unknown table %', p_table_name;
  END IF;

  EXECUTE format('ALTER TABLE %I RENAME TO %I', p_table_name, p_table_name || '_old');
  EXECUTE format('ALTER TABLE %I RENAME TO %I', p_table_name || '_staging', p_table_name);
  EXECUTE format('ALTER TABLE %I RENAME TO %I', p_table_name || '_old', p_table_name || '_staging');
  EXECUTE format('TRUNCATE TABLE %I', p_table_name || '_staging');
END;
$$;
